APPROVED_VALUE_SHA256 = {'english': {'DOTA_Tooltip_ability_ability_survival_blademaster_agility_Description': 'd5a6cb70f9e4dc9c2125b303561c7a4773993d310c31989ac3205d4a8443b67c', 'DOTA_Tooltip_ability_ability_survival_monkey_king_fury_Description': 'b4cc64f21eac2cd6ce8a54e7f9209dc52a6a0de5cc020edd3a02933d2afeae04'}, 'schinese': {'DOTA_Tooltip_ability_ability_survival_blademaster_agility_Description': '8d77616b63380d54b72dca7d0971b91997a73d4e73f90af2dc7659a8277635fd', 'DOTA_Tooltip_ability_ability_survival_monkey_king_fury_Description': 'e0f0a965fbe273bc7686181bf8df7c28b0a9263a51d6324b79225fc16f93c89c'}}
PATHS = frozenset(BASELINES)

def need(value, code):
    if not value:
        raise ValueError(code)

def sha(raw):
    return hashlib.sha256(raw).hexdigest()

def fingerprint(raw):
    return {'sha256': sha(raw), 'bytes': len(raw), 'md5': hashlib.md5(raw).hexdigest()}
TRAINING_NAME_BLOCK = '        "building_endless_training_target" "长青轮纹"\n        "npc_dota_unit_building_endless_training_target" "长青轮纹"\n'.encode('utf-8')
TRAINING_NAME_KEYS = (b'"building_endless_training_target"', b'"npc_dota_unit_building_endless_training_target"')

def _without_training_name(raw):
    counts = tuple((raw.count(key) for key in TRAINING_NAME_KEYS))
    if counts == (0, 0):
        return raw
    need(counts == (1, 1), 'localization_training_name_alias_pair_required')
    opening = re.search(b'(?m)^[ \\t]*"Tokens"[ \\t]*\\n[ \\t]*\\{\\n', raw)
    need(opening is not None, 'localization_training_name_tokens_opening_required')
    start = opening.end()
    need(raw[start:start + len(TRAINING_NAME_BLOCK)] == TRAINING_NAME_BLOCK, 'localization_training_name_value_or_layout_changed')
    return raw[:start] + raw[start + len(TRAINING_NAME_BLOCK):]

def _mask(raw, path=None):
    need(type(raw) is bytes and 0 < len(raw) <= MAX_BYTES, 'localization_bounded_bytes_required')
    need(b'\r' not in raw and b'\x00' not in raw, 'localization_exact_git_lf_required')
    raw.decode('utf-8-sig')
    raw = _without_training_name(raw)
    values = {}
    masked = raw
    for token in TOKENS_BY_PATH.get(path, TOKENS):
        expression = b'(?m)^([ \\t]*"' + token.encode('ascii') + b'"[ \\t]+")((?:\\\\.|[^"\\\\\\r\\n])*)("[ \\t]*$)'
        matches = list(re.finditer(expression, masked))
        need(len(matches) == 1, 'localization_exact_single_reviewed_token_required')
        found = matches[0]
        value = found.group(2)
        need(0 < len(value) <= 4096, 'localization_bounded_value_required')
        values[token] = sha(value)
        masked = masked[:found.start(2)] + b'__REVIEWED_HERO_W_DESCRIPTION__' + masked[found.end(2):]
    return (sha(masked), values)

def verify_projection(path, content_raw, game_raw):
    """Pure full-byte proof, repeated by collector and independently by signer."""
    need(path in PATHS, 'unreviewed_localization_projection_path')
    content_mask, content_values = _mask(content_raw, path)
    game_mask, game_values = _mask(game_raw, path)
    need((TRAINING_NAME_KEYS[0] in content_raw) == (TRAINING_NAME_KEYS[0] in game_raw), 'localization_training_name_dual_source_required')
    language = path.rsplit('_', 1)[1][:-4]
    expected = APPROVED_VALUES_BY_PATH[path]
    need(content_values == game_values == expected, 'localization_reviewed_values_or_projection_changed')
    need(content_mask == BASELINES[path]['content']['masked_sha256'] and game_mask == BASELINES[path]['game']['masked_sha256'], 'localization_unreviewed_bytes_outside_two_tokens')
    return {'schema': 1, 'kind': KIND, 'resource': path, 'baselines': deepcopy(BASELINES[path]), 'masked_sha256': {'game': game_mask, 'content': content_mask}, 'value_sha256': dict(content_values), 'sources': {'game': fingerprint(game_raw), 'content': fingerprint(content_raw)}, 'output': fingerprint(game_raw)}

def validate_metadata(path, proof, inputs, output, source_fingerprints):
    """Ledger shape checks; only verify_projection(actual bytes) proves content."""
    need(path in PATHS and isinstance(proof, dict), 'localization_projection_proof_required')
    need(set(proof) == {'schema', 'kind', 'resource', 'baselines', 'masked_sha256', 'value_sha256', 'sources', 'output'} and type(proof['schema']) is int and (proof['schema'] == 1) and (proof['kind'] == KIND) and (proof['resource'] == path), 'localization_projection_schema_changed')
    expected_inputs = {'game:' + path, 'content:' + path}
    need(set(inputs) == expected_inputs and set(source_fingerprints) == expected_inputs, 'localization_exact_dual_source_binding_required')
    need(proof['baselines'] == BASELINES[path] and proof['masked_sha256'] == {role: BASELINES[path][role]['masked_sha256'] for role in ('game', 'content')} and (proof['value_sha256'] == APPROVED_VALUES_BY_PATH[path]), 'localization_reviewed_baseline_or_values_changed')
    expected_sources = {role: source_fingerprints[role + ':' + path] for role in ('game', 'content')}
    need(proof['sources'] == expected_sources and all((inputs[role + ':' + path] == expected_sources[role]['sha256'] for role in expected_sources)) and (proof['output'] == output == expected_sources['game']), 'localization_source_or_output_fingerprint_changed')
